pages.inlineStyles:
.prices__inner {
		padding-top: 60px;
	}

	.prices__text {
		position: relative;
	}

	.prices__table-preview {
		position: relative;
		overflow: hidden;
		padding-bottom: 260px;
	}

	.prices__table-preview::after {
		content: "";
		position: absolute;
		left: 0;
		right: 0;
		bottom: 0;
		height: 320px;
		background: linear-gradient(180deg, rgba(242, 244, 248, 0) 0%, rgba(242, 244, 248, 0.18) 18%, rgba(242, 244, 248, 0.56) 42%, rgba(242, 244, 248, 0.88) 72%, #F2F4F8 100%);
		pointer-events: none;
	}

	.prices__cta {

	}

	.prices__cta {
		position: absolute;
		left: 0;
		right: 0;
		bottom: 0;
		z-index: 2;
		padding: 24px 0;
	}

	.prices__cta-card {
		display: grid;
		grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.6fr);
		gap: 20px;
		align-items: center;
		padding: 28px 32px;
		background: rgba(255, 255, 255, 0.96);
		border: 1px solid rgba(13, 178, 90, 0.18);
		border-radius: 24px;
		box-shadow: 0 22px 60px rgba(28, 37, 38, 0.14);
		backdrop-filter: blur(6px);
	}

	.prices__cta-copy h3 {
		margin: 0 0 10px;
		font-size: 2rem;
		line-height: 1.05;
		font-weight: 700;
		color: #111;
	}

	.prices__cta-copy p {
		margin: 0;
		font-size: 1rem;
		line-height: 1.5;
		color: #4f5a5b;
		max-width: 420px;
	}

	.prices__cta-form {
		display: grid;
		grid-template-columns: minmax(0, 1fr) minmax(180px, 220px) minmax(190px, 230px);
		gap: 14px;
		align-items: end;
	}

	.prices__cta .site-form-consent {
		grid-column: 1 / -1;
		width: 100%;
	}

	.prices__cta-form .form-input,
	.prices__cta-form .form-select,
	.prices__cta-form .form-button {
		margin: 0;
		align-self: end;
	}

	.prices__cta-form .form-select {
		padding: 0;
		border: 0;
		background: transparent;
		box-shadow: none;
	}

	.prices__cta-form .form-input {
		display: flex;
		align-items: end;
	}

	.prices__cta-form .form-input input {
    	margin-bottom: 0;
	}	

	.prices__cta-form .form-input input,
	.prices__cta-form .form-select select {
		width: 100%;
		height: 60px;
		min-height: 60px;
		padding: 18px 18px;
		border: 2px solid #0DB25A;
		border-radius: 14px;
		background: #fff;
		color: #1c2526;
		box-shadow: none;
	}

	.prices__cta-form .form-select select {
		appearance: none;
		-webkit-appearance: none;
		-moz-appearance: none;
		background-image: linear-gradient(45deg, transparent 50%, #0DB25A 50%), linear-gradient(135deg, #0DB25A 50%, transparent 50%);
		background-position: calc(100% - 20px) calc(50% - 4px), calc(100% - 14px) calc(50% - 4px);
		background-size: 6px 6px, 6px 6px;
		background-repeat: no-repeat;
	}

	.prices__cta-form .form-button__button {
		width: 100%;
		height: auto;
		min-height: 60px;
		padding: 12px 18px;
		border-radius: 14px;
		white-space: normal;
		line-height: 1.15;
		text-align: center;
		display: flex;
		align-items: center;
		justify-content: center;
	}

	@media (max-width: 991px) {
		.prices__table-preview {
			padding-bottom: 460px;
		}

		.prices__table-preview::after {
			height: 420px;
		}

		.prices__cta-card {
			grid-template-columns: 1fr;
			gap: 14px;
			padding: 20px 22px;
			border-radius: 20px;
		}

		.prices__cta-form {
			grid-template-columns: 1fr;
			gap: 10px;
		}

		.prices__cta {
			padding: 16px 0;
		}

		.prices__cta-copy h3 {
			font-size: 1.6rem;
			margin-bottom: 6px;
		}

		.prices__cta-copy p {
			font-size: 0.95rem;
			line-height: 1.4;
		}

		.prices__cta-form .form-input input,
		.prices__cta-form .form-select select {
			height: 52px;
			min-height: 52px;
			padding: 14px 16px;
		}

		.prices__cta-form .form-button__button {
			min-height: 52px;
			padding: 10px 16px;
		}
	}

	@media (max-width: 575px) {
		.prices__table-preview {
			padding-bottom: 520px;
		}

		.prices__table-preview::after {
			height: 520px;
			background: linear-gradient(180deg, rgba(242, 244, 248, 0) 0%, rgba(242, 244, 248, 0.28) 12%, rgba(242, 244, 248, 0.68) 30%, rgba(242, 244, 248, 0.92) 56%, #F2F4F8 100%);
		}

		.prices__cta {
			padding: 14px 0;
		}

		.prices__cta-card {
			padding: 20px 16px;
			border-radius: 18px;
		}

		.prices__cta-copy h3 {
			font-size: 1.5rem;
		}
